// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address u) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        try c.addToBalance{value: 0}() {} catch { return; }
        uint256 b0;
        try c.getBalance(u) returns (uint256 __r) { b0 = __r; } catch { return; }
        try c.withdrawBalance() { } catch {}
        uint256 b1;
        try c.getBalance(u) returns (uint256 __r) { b1 = __r; } catch { return; }
        assertTrue(u == address(this) || b1 == b0);
    }

    function testFuzz_run(address u) public {
        vm.assume(u.code.length == 0 && uint160(u) > 0xffff && u != address(this) && u != address(c) && u != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && u != 0x000000000000000000636F6e736F6c652e6c6f67 && u != 0x4e59b44847b379578588920cA78FbF26c0B4956C && u != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(u);
    }

    receive() external payable {}
}
